css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .base { position: absolute; left: 10%; right: 10%; bottom: 2%; height: 10%; border-radius: 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.loader .deck { position: absolute; left: 6%; right: 6%; height: 9%; border-radius: 4px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: scissor-deck calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .rig { position: absolute; left: 22%; right: 22%; bottom: 12%; height: 76%; }
.loader .rig span { position: absolute; left: 0; width: 100%; height: 6%; border-radius: 3px; background: var(--accent); animation: scissor-arm calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .rig span:nth-of-type(1) { bottom: 4%; }
.loader .rig span:nth-of-type(2) { bottom: 4%; animation-name: scissor-arm-mirror; }
.loader .rig span:nth-of-type(3) { bottom: 30%; }
.loader .rig span:nth-of-type(4) { bottom: 30%; animation-name: scissor-arm-mirror; }
.loader .rig span:nth-of-type(5) { bottom: 56%; }
.loader .rig span:nth-of-type(6) { bottom: 56%; animation-name: scissor-arm-mirror; }
@keyframes scissor-deck { 0%, 8% { bottom: 26%; } 52%, 76% { bottom: 82%; } 96%, 100% { bottom: 26%; } }
@keyframes scissor-arm { 0%, 8% { transform: rotate(14deg) scaleX(1); } 52%, 76% { transform: rotate(62deg) scaleX(.62); } 96%, 100% { transform: rotate(14deg) scaleX(1); } }
@keyframes scissor-arm-mirror { 0%, 8% { transform: rotate(-14deg) scaleX(1); } 52%, 76% { transform: rotate(-62deg) scaleX(.62); } 96%, 100% { transform: rotate(-14deg) scaleX(1); } }
